# region: intake
def intake(raw):
    out = []
    for tok in raw[1:]:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: shape
def shape(xs, offset=4):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(emit(sift(shape(gather(intake(raw))))))

